17	/**
18	 * lvgl_toast.c — Top-of-screen toast popup (transient notice, not in chat history).
19	 *
20	 * Pattern follows qrcode_display.c: an async entry copies the request onto the
21	 * heap and lv_async_call()'s into the LVGL thread, where the real widget is
22	 * built on top of lv_screen_active().  A one-shot lv_timer triggers a fade-out
23	 * animation that deletes the object; a CLICKED handler allows early dismiss.
24	 *
25	 * Only one toast is shown at a time — a newer toast replaces an older one.
26	 */
27	
28	#include "ui/lvgl_toast.h"
29	#include "agent_config.h"
30	
31	#include <string.h>
32	#include <stdlib.h>
33	#include <syslog.h>
34	
35	#if defined(CONFIG_AI_AGENT_LVGL_UI) && defined(CONFIG_GRAPHICS_LVGL)
36	#include <lvgl/lvgl.h>
37	
38	/* App-owned pre-rasterized MiSans-16 CJK font (compiled from
39	 * src/ui/lv_font_misans_16_cjk.c, same pattern as xiaozhi_gui's
40	 * font_awesome_*.c) — declared here instead of patching apps_graphics_lvgl. */
41	LV_FONT_DECLARE(lv_font_misans_16_cjk);
42	
43	static const char *TAG = "lvgl_toast";
44	
45	#define TOAST_TITLE_LEN 32
46	#define TOAST_BODY_LEN  160
47	#define TOAST_DEFAULT_MS 4000  /* auto-dismiss if caller passes 0 */
48	
49	/* Heap payload for the async hop into the LVGL thread. */
50	typedef struct {
51	    char title[TOAST_TITLE_LEN];
52	    char body[TOAST_BODY_LEN];
53	    uint32_t bar_color;
54	    uint32_t duration_ms;
55	} toast_payload_t;
56	
57	static lv_obj_t *s_toast = NULL;        /* active toast object, NULL if none */
58	static lv_timer_t *s_timer = NULL;     /* auto-dismiss timer */
59	
60	/* ── Cleanup (must run on LVGL thread) ─────────────────────────── */
61	
62	static void toast_cleanup(void)
63	{
64	    if (s_timer) {
65	        lv_timer_delete(s_timer);
66	        s_timer = NULL;
67	    }
68	    if (s_toast) {
69	        lv_obj_delete(s_toast);
70	        s_toast = NULL;
71	    }
72	}
73	
74	/* ── Event callbacks (LVGL thread) ──────────────────────────────── */
75	
76	static void toast_click_cb(lv_event_t *e)
77	{
78	    (void)e;
79	    syslog(LOG_INFO, "[%s] toast dismissed by tap\n", TAG);
80	    toast_cleanup();
81	}
82	
83	static void toast_anim_ready_cb(lv_anim_t *a)
84	{
85	    lv_obj_t *obj = (lv_obj_t *)a->var;
86	    if (obj == s_toast) {
87	        s_toast = NULL;   /* cleared so toast_cleanup won't double-delete */
88	    }
89	    if (s_timer) {
90	        lv_timer_delete(s_timer);
91	        s_timer = NULL;
92	    }
93	    lv_obj_delete(obj);
94	}
95	
96	static void toast_timeout_cb(lv_timer_t *t)
97	{
98	    (void)t;
99	    s_timer = NULL;  /* timer auto-deletes (repeat_count=1 + auto_delete) */
100	    if (!s_toast) {
101	        return;
102	    }
103	    syslog(LOG_INFO, "[%s] toast auto-dismiss (fade out)\n", TAG);
104	
105	    /* Fade out 300ms then delete */
106	    lv_anim_t a;
107	    lv_anim_init(&a);
108	    lv_anim_set_var(&a, s_toast);
109	    lv_anim_set_values(&a, LV_OPA_COVER, LV_OPA_TRANSP);
110	    lv_anim_set_time(&a, 300);
111	    lv_anim_set_ready_cb(&a, toast_anim_ready_cb);
112	    lv_anim_start(&a);
113	}
114	
115	/* ── Build the toast widget (LVGL thread) ──────────────────────── */
116	
117	static void toast_build(const toast_payload_t *p)
118	{
119	    /* Replace any existing toast */
120	    toast_cleanup();
121	
122	    lv_obj_t *scr = lv_screen_active();
123	    if (!scr) {
124	        syslog(LOG_ERR, "[%s] no active screen\n", TAG);
125	        return;
126	    }
127	
128	    lv_display_t *disp = lv_display_get_default();
129	    lv_coord_t disp_w = disp ? lv_display_get_horizontal_resolution(disp) : 466;
130	    lv_coord_t disp_h = disp ? lv_display_get_vertical_resolution(disp) : 466;
131	    (void)disp_h;
132	
133	    lv_obj_t *toast = lv_obj_create(scr);
134	    if (!toast) {
135	        syslog(LOG_ERR, "[%s] lv_obj_create failed\n", TAG);
136	        return;
137	    }
138	    s_toast = toast;
139	
140	    lv_coord_t w = disp_w - 40;
141	    if (w < 200) w = 200;
142	    lv_obj_set_size(toast, w, 80);
143	    lv_obj_align(toast, LV_ALIGN_TOP_MID, 0, 12);
144	    lv_obj_set_style_bg_color(toast, lv_color_hex(0x2a2a3e), 0);
145	    lv_obj_set_style_bg_opa(toast, LV_OPA_COVER, 0);
146	    lv_obj_set_style_border_color(toast, lv_color_hex(p->bar_color), 0);
147	    lv_obj_set_style_border_width(toast, 2, 0);
148	    lv_obj_set_style_border_side(toast, LV_BORDER_SIDE_FULL, 0);
149	    lv_obj_set_style_radius(toast, 8, 0);
150	    lv_obj_set_style_pad_all(toast, 8, 0);
151	    lv_obj_clear_flag(toast, LV_OBJ_FLAG_SCROLLABLE);
152	    lv_obj_add_flag(toast, LV_OBJ_FLAG_CLICKABLE);
153	    lv_obj_add_event_cb(toast, toast_click_cb, LV_EVENT_CLICKED, NULL);
154	
155	    /* Left color bar */
156	    lv_obj_t *bar = lv_obj_create(toast);
157	    lv_obj_set_size(bar, 6, 64);
158	    lv_obj_align(bar, LV_ALIGN_LEFT_MID, 0, 0);
159	    lv_obj_set_style_bg_color(bar, lv_color_hex(p->bar_color), 0);
160	    lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
161	    lv_obj_set_style_radius(bar, 3, 0);
162	    lv_obj_set_style_border_width(bar, 0, 0);
163	    lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
164	
165	    /* Title label */
166	    lv_obj_t *title = lv_label_create(toast);
167	    if (title) {
168	        lv_label_set_text(title, p->title);
169	        lv_obj_set_style_text_font(title, &lv_font_misans_16_cjk, 0);
170	        lv_obj_set_style_text_color(title, lv_color_hex(0xe8e8e8), 0);
171	        lv_obj_align(title, LV_ALIGN_TOP_LEFT, 14, 4);
172	    }
173	
174	    /* Body label (ellipsis on overflow) */
175	    lv_obj_t *body = lv_label_create(toast);
176	    if (body) {
177	        lv_label_set_text(body, p->body);
178	        lv_obj_set_style_text_font(body, &lv_font_misans_16_cjk, 0);
179	        lv_obj_set_style_text_color(body, lv_color_hex(0xc8c8d0), 0);
180	        lv_label_set_long_mode(body, LV_LABEL_LONG_DOT);
181	        lv_obj_set_width(body, w - 28);
182	        lv_obj_align(body, LV_ALIGN_BOTTOM_LEFT, 14, -4);
183	    }
184	
185	    /* Auto-dismiss timer */
186	    s_timer = lv_timer_create(toast_timeout_cb, p->duration_ms, NULL);
187	    if (s_timer) {
188	        lv_timer_set_repeat_count(s_timer, 1);
189	        lv_timer_set_auto_delete(s_timer, true);
190	    }
191	
192	    syslog(LOG_INFO, "[%s] toast: %s | %s\n", TAG, p->title, p->body);
193	}
194	
195	/* ── Async entry (LVGL thread) ────────────────────────────────── */
196	
197	static void toast_async_cb(void *data)
198	{
199	    toast_payload_t *p = (toast_payload_t *)data;
200	    if (!p) {
201	        return;
202	    }
203	    toast_build(p);
204	    free(p);
205	}
206	
207	/* ── Public API ───────────────────────────────────────────────── */
208	
209	void lvgl_toast_show_async(const char *title, const char *body,
210	                           uint32_t bar_color, uint32_t duration_ms)
211	{
212	    if (!title || !body) {
213	        return;
214	    }
215	
216	    toast_payload_t *p = (toast_payload_t *)malloc(sizeof(toast_payload_t));
217	    if (!p) {
218	        syslog(LOG_ERR, "[%s] payload alloc failed\n", TAG);
219	        return;
220	    }
221	    strlcpy(p->title, title, sizeof(p->title));
222	    strlcpy(p->body, body, sizeof(p->body));
223	    p->bar_color = bar_color;
224	    p->duration_ms = duration_ms ? duration_ms : TOAST_DEFAULT_MS;
225	
226	    if (lv_async_call(toast_async_cb, p) == LV_RESULT_OK) {
227	        /* async scheduled; payload freed in callback */
228	        return;
229	    }
230	
231	    /* lv_async_call failed — free here to avoid leak */
232	    syslog(LOG_ERR, "[%s] lv_async_call failed\n", TAG);
233	    free(p);
234	}
235	
236	#else /* !CONFIG_AI_AGENT_LVGL_UI || !CONFIG_GRAPHICS_LVGL */
237	
238	void lvgl_toast_show_async(const char *title, const char *body,
239	                           uint32_t bar_color, uint32_t duration_ms)
240	{
241	    (void)bar_color;
242	    (void)duration_ms;
243	    if (title && body) {
244	        syslog(LOG_INFO, "[lvgl_toast] (LVGL unavailable) %s: %s\n", title, body);
245	    }
246	}
247	
248	#endif /* CONFIG_AI_AGENT_LVGL_UI && CONFIG_GRAPHICS_LVGL */
